sig Person { parent: set Person }
fun ancestors[p: Person]: set Person { p.^parent }
fun roots: set Person { Person - parent.Person }
fun grand: Person -> Person { parent.parent }
assert Acyclic { all p: Person | p not in ancestors[p] }
AcyclicFails: check Acyclic for 2 but 0 Int
GrandBinary: run { some grand } for 3 but 0 Int
Roots: run { some roots and some Person - roots } for 2 but 0 Int
ReceiverFun: run { some p: Person | some p.ancestors } for 2 but 0 Int
BoxJoin: run { some p: Person | some parent[p] and parent[p] != p.parent } for 2 but 0 Int

sig A { r: set A }
fun out[x: A]: set A { x.r }
pred reaches[x, y: A] { y in out[x] + out[out[x]] }
pred symmetric { all x, y: A | reaches[x, y] => reaches[y, x] }
fun both[x: A, y: A]: set A { out[x] & out[y] }
Sym: run { symmetric and some r } for 2 but 0 Int
TwoStep: run { some x, y: A | reaches[x, y] and y not in out[x] } for 3 but 0 Int
Common: run { some disj x, y: A | some both[x, y] } for 2 but 0 Int
assert ReachOut { all x, y: A | y in out[x] => reaches[x, y] }
ReachOutHolds: check ReachOut for 3 but 0 Int

sig Node { edge: set Node }
pred connected[a, b: Node] { b in a.^edge }
pred selfLoop[n: Node] { n in n.edge }
SomeConnected: run { some a, b: Node | connected[a, b] } for 2 but 0 Int
RunWithParams: run connected for 2 but 0 Int
RunLoop: run selfLoop for 1 but 0 Int
assert Trans { all a, b, c: Node | connected[a, b] and connected[b, c] => connected[a, c] }
TransHolds: check Trans for 3 but 0 Int
Receiver: run { some a, b: Node | a.connected[b] and not b.connected[a] } for 2 but 0 Int

sig S { f: set S }
pred related[x: S, y: S] { x -> y in f }
pred sym[x, y: S] { related[x, y] <=> related[y, x] }
fun pairs: S -> S { f & ~f }
assert SymSelf { all x: S | sym[x, x] }
SymSelfHolds: check SymSelf for 3 but 0 Int
AsymPair: run { some x, y: S | not sym[x, y] } for 2 but 0 Int
SymPairs: run { some pairs and pairs = f } for 2 but 0 Int
assert PairsSymmetric { pairs = ~pairs }
PairsHold: check PairsSymmetric for 3 but 0 Int

sig Item { price: one Tier }
abstract sig Tier {}
one sig Low, High extends Tier {}
pred expensive[i: Item] { i.price = High }
pred mixed[a, b: Item] { a.price != b.price }
pred samePrice[disj a, b: Item] { a.price = b.price }
Expensive: run expensive for 2 but 0 Int
Mixed: run mixed for 2 but 0 Int
MixedOne: run mixed for 1 but 0 Int
DisjPair: run samePrice for 1 but 0 Int
DisjPairTwo: run samePrice for 2 but 0 Int
